const e = $input.first().json;
const wf = e.workflow || {};
const ex = e.execution || {};
return [{ json: {
  workflow: wf.name || 'unknown', execution_id: ex.id || null, failed_node: ex.lastNodeExecuted || null,
  message: (ex.error && ex.error.message) || 'unknown error', mode: ex.mode || null,
} }];

const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const hdr = (v) => String(v ?? '').replace(/[\u0000-\u001f\u007f]+/g, ' ').trim().slice(0, 120);

const d = $input.first().json;
const row = (k, v) => `<tr><td style="padding:3px 12px 3px 0;color:#666">${esc(k)}</td><td>${esc(v)}</td></tr>`;
return [{ json: {
  to: $env.OWNER_EMAIL,
  subject: `[ERROR] ${hdr(d.workflow)} failed at ${hdr(d.failed_node)}`,
  html: `<div style="font-family:Arial,sans-serif"><p><strong>A workflow execution failed.</strong></p><table>${row('Workflow', d.workflow)}${row('Failed node', d.failed_node)}${row('Execution ID', d.execution_id)}${row('Error', d.message)}</table></div>`,
} }];

